import openpyxl
from openpyxl.styles import PatternFill, Alignment
wb = openpyxl.load_workbook('output.xlsx')
ws = wb['Taul1']

races = {2:6, 7:14, 15:28}
for s, end in races.items():
    src = f"$G${s}:$G${end}"
    for c in range(8, 20):
        cell = ws.cell(s, c)
        cell.value = (
            f'=IF(OR(COLUMN()-7>$C${s}, INDEX({src},COLUMN()-7)=""),"",'
            f'VALUE(INDEX({src},COLUMN()-7)))'
        )

fill = PatternFill(start_color='E2EFD9', end_color='E2EFD9', fill_type='solid')
for r in range(2,29):
    for c in range(8,20):
        ws.cell(r,c).fill = fill
        ws.cell(r,c).number_format = 'General'

for r in range(1,29):
    for c in range(8,30):
        ws.cell(r,c).alignment = Alignment(horizontal='center')

wb.save('output.xlsx')
print('done')
EOF
